def is_woodall(x):
    """Write a function to check if the given number is woodball or not.

    A Woodall number is a positive integer of the form
    ``n * 2**n - 1`` for some positive integer ``n``
    (1, 7, 23, 63, 159, 383, ...).

    Non-integer values are not Woodall numbers.
    """
    if isinstance(x, bool):
        return False
    if isinstance(x, float):
        if not x.is_integer():
            return False
        x = int(x)
    if not isinstance(x, int):
        return False
    if x < 1:
        return False

    # W(n) = n * 2**n - 1 is strictly increasing for n >= 1 and
    # log2(x + 1) = n + log2(n) when x is Woodall, so starting just
    # below log2(x + 1) is within a few steps of the only possible n.
    n = max(1, (x + 1).bit_length() - 1)
    while n > 1 and (n << n) - 1 > x:
        n -= 1
    while (n << n) - 1 < x:
        n += 1
    return (n << n) - 1 == x
